package com.trampolim.api.config;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
class ProductionSecurityGuardTest {
 MockEnvironment safe(){var e=new MockEnvironment();e.setActiveProfiles("prod");e.withProperty("app.cors.allowed-origins","https://app.example.test, https://learn.example.test").withProperty("app.frontend-url","https://app.example.test").withProperty("spring.jpa.hibernate.ddl-auto","validate").withProperty("spring.flyway.enabled","true").withProperty("spring.flyway.baseline-on-migrate","false").withProperty("spring.flyway.clean-disabled","true").withProperty("app.mail.enabled","true").withProperty("spring.mail.host","smtp.example.test").withProperty("spring.mail.properties.mail.smtp.starttls.enable","true").withProperty("spring.mail.properties.mail.smtp.starttls.required","true");
 int n=0;for(String p:List.of("spring.datasource","trampolim.datasource.empresas","trampolim.datasource.capacita")){e.withProperty(p+".enabled","true").withProperty(p+".username","isolated_role_"+n).withProperty(p+".password","synthetic-database-password-"+n++);}
 for(String p:List.of("api.security.token.secret","trails.auth.empresas.secret","trails.auth.capacita.secret","operations.monitoring-key","radar.bridge-secret"))e.withProperty(p,"synthetic-exclusive-secret-0123456789-"+n++);return e;
 }
 void rejects(String key,String value){var e=safe().withProperty(key,value);var error=assertThrows(IllegalStateException.class,()->new ProductionSecurityGuard(e).afterPropertiesSet());assertTrue(error.getMessage().contains(key));if(value.length()>15)assertFalse(error.getMessage().contains(value));}
 @Test void developmentDoesNotRequireProductionSettings(){assertDoesNotThrow(()->new ProductionSecurityGuard(new MockEnvironment()).afterPropertiesSet());}
 @Test void acceptsIsolatedProductionSettingsAndAlias(){assertDoesNotThrow(()->new ProductionSecurityGuard(safe()).afterPropertiesSet());var e=safe();e.setActiveProfiles("production");assertDoesNotThrow(()->new ProductionSecurityGuard(e).afterPropertiesSet());}
 @Test void rejectsWildcardHttpAndCredentialedBrowserOrigins(){for(String value:List.of("*","http://app.example.test","https://user:secret@app.example.test","https://app.example.test/path","https://app.example.test?secret=private","https://app.example.test,"))rejects("app.cors.allowed-origins",value);rejects("app.cors.allowed-origin-patterns","https://*.example.test");rejects("app.frontend-url","http://app.example.test");}
 @Test void rejectsDestructiveOrAmbiguousPersistenceConfiguration(){rejects("spring.jpa.hibernate.ddl-auto","update");rejects("spring.flyway.enabled","false");rejects("spring.flyway.baseline-on-migrate","true");rejects("spring.flyway.clean-disabled","false");rejects("trampolim.datasource.empresas.enabled","false");rejects("trampolim.datasource.capacita.enabled","false");}
 @Test void rejectsLegacyAuthentication(){for(String key:List.of("trails.auth.legacy-token.enabled","trails.auth.legacy-company.enabled","trails.auth.legacy-organizations.enabled"))rejects(key,"true");}
 @Test void rejectsSharedWeakOrPublicSecretsWithoutEchoingThem(){rejects("operations.monitoring-key","");rejects("radar.bridge-secret","REPLACE_public_example_value_0123456789");var e=safe();e.withProperty("operations.monitoring-key",e.getProperty("api.security.token.secret"));assertThrows(IllegalStateException.class,()->new ProductionSecurityGuard(e).afterPropertiesSet());}
 @Test void rejectsSuperuserWeakPasswordAndSharedDatabaseRoles(){rejects("spring.datasource.username","postgres");rejects("spring.datasource.password","short");rejects("spring.datasource.password","dev_empresas_only");rejects("trampolim.datasource.capacita.password","dev_capacita_only");rejects("trampolim.datasource.empresas.username","isolated_role_0");}
 @Test void requiresMailVerificationAndEncryptedTransport(){rejects("app.mail.enabled","false");rejects("spring.mail.properties.mail.smtp.starttls.required","false");rejects("spring.mail.host","");var e=safe().withProperty("spring.mail.properties.mail.smtp.starttls.enable","false").withProperty("spring.mail.properties.mail.smtp.ssl.enable","true");assertDoesNotThrow(()->new ProductionSecurityGuard(e).afterPropertiesSet());}
}
